<html lang="vi"><head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#224086">
<title>@yield('title', 'The HBG NFC')</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,Arial,sans-serif;color:#1c2840;background:#f3f6fb}*{box-sizing:border-box}body{margin:0}a{color:#224086;text-decoration:none}a:hover{text-decoration:underline}.container{max-width:1050px;margin:0 auto;padding:24px}.panel{background:#fff;border-radius:18px;padding:28px;box-shadow:0 8px 28px #15284813}.top{background:#224086;color:white;padding:16px 24px;display:flex;align-items:center;justify-content:space-between;gap:12px}.top a{color:white}.brand{font-size:20px;font-weight:850;letter-spacing:2px}.btn{display:inline-block;border:0;border-radius:10px;padding:11px 16px;background:#224086;color:#fff;cursor:pointer;font-size:14px;text-align:center}.btn:hover{opacity:.9;color:white;text-decoration:none}.btn.secondary{background:#ecf0fa;color:#224086}.btn.gold{background:#d9a65b;color:#1c2840}.input{width:100%;border:1px solid #ced7e6;border-radius:9px;padding:11px 12px;font:inherit;background:#fff}.field{margin-bottom:15px}.field label{display:block;font-size:13px;font-weight:650;margin-bottom:6px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}.muted{color:#68758c;font-size:13px}.alert{padding:12px 14px;background:#ecf8ee;color:#136b35;border-radius:10px;margin-bottom:16px}.error{color:#b52436;font-size:13px;margin-top:4px}table{border-collapse:collapse;width:100%}td,th{text-align:left;border-bottom:1px solid #e8edf5;padding:12px 8px;font-size:14px}th{font-size:12px;color:#66728b}.actions{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.break{overflow-wrap:anywhere}.cardphoto{height:112px;width:112px;object-fit:cover;border-radius:50%;border:5px solid white;box-shadow:0 5px 18px #15284822}.placeholder{display:flex;align-items:center;justify-content:center;background:#e7edfb;color:#224086;font-size:42px;font-weight:800}.profile{max-width:480px;margin:35px auto;padding:0;overflow:hidden}.hero{background:linear-gradient(145deg,#224086,#0e2459);color:white;padding:36px 24px 28px;text-align:center}.hero h1{margin:12px 0 5px;font-size:25px}.tag{display:inline-block;padding:5px 11px;background:#ffffff20;border-radius:20px;font-size:12px}.details{padding:23px}.detail{border-bottom:1px solid #eef0f6;padding:12px 0}.detail small{display:block;color:#6e7891;margin-bottom:3px}.detail span{font-weight:550;overflow-wrap:anywhere}.profile-footer{border-top:1px solid #eef0f6;padding:17px;text-align:center;color:#68758c;font-size:12px}@media(max-width:650px){.container{padding:12px}.panel{padding:18px}.grid{grid-template-columns:1fr}.profile{margin:12px auto}table{display:block;overflow:auto;white-space:nowrap}}
